exercises.solution:
function lerPontos(texto) {
  const pontos = Number(texto);
  if (Number.isNaN(pontos)) {
    return null;
  } else {
    return pontos;
  }
}

function mostrarPontos(texto) {
  const pontos = lerPontos(texto);
  if (pontos === null) {
    console.log(`"${texto}" não é um número`);
  } else {
    console.log(`Pontos do cartão: ${pontos}`);
  }
}

mostrarPontos('120');
mostrarPontos('cem');
mostrarPontos('45');

