exercises.solution:
function calcularMedia(soma, provas) {
  if (provas === 0) {
    return null;
  } else {
    return soma / provas;
  }
}

function mostrarMedia(nome, soma, provas) {
  const media = calcularMedia(soma, provas);
  if (media === null) {
    console.log(`${nome}: sem provas feitas`);
  } else {
    console.log(`${nome}: média ${media.toFixed(1)}`);
  }
}

mostrarMedia('Rita', 24, 3);
mostrarMedia('Téo', 0, 0);
mostrarMedia('Davi', 0, 2);
mostrarMedia('Nina', 17, 2);
